1	import { Fragment } from "react";
2	import { cn } from "@/lib/utils";
3	import { Badge } from "@/components/ui/badge";
4	import { Button } from "@/components/ui/button";
5	import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
6	import { XCircle } from "lucide-react";
7	import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
8	import { format } from "date-fns";
9	
10	interface CustomStage {
11	  name: string;
12	  color: string;
13	}
14	
15	interface StageTrackerProps {
16	  currentStage: string;
17	  updatedAt?: string | null;
18	  onStageChange: (stage: HiringStage) => void;
19	  disabled?: boolean;
20	  /** Optional custom stages — when provided renders them instead of hardcoded STAGE_ORDER */
21	  customStages?: CustomStage[];
22	}
23	
24	const STAGE_LABELS: Record<string, string> = {
25	  applied: "Applied",
26	  screened: "Screened",
27	  interview: "Interview",
28	  offer: "Offer",
29	  hired: "Hired",
30	};
31	
32	const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled, customStages }: StageTrackerProps) => {
33	  // When customStages provided, derive stage order from them; otherwise use hardcoded STAGE_ORDER
34	  const effectiveStages: string[] = customStages
35	    ? customStages.map((s) => s.name.toLowerCase())
36	    : STAGE_ORDER;
37	
38	  const effectiveLabels: Record<string, string> = customStages
39	    ? Object.fromEntries(customStages.map((s) => [s.name.toLowerCase(), s.name]))
40	    : STAGE_LABELS;
41	
42	  const normalizedCurrent = currentStage.toLowerCase();
43	  const currentIndex = normalizedCurrent === "rejected" ? -1 : effectiveStages.indexOf(normalizedCurrent);
44	  const isRejected = normalizedCurrent === "rejected";
45	
46	  return (
47	    <div className="flex items-center gap-3 py-1">
48	      <span className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>
49	
50	      {/* Dots + connectors + labels */}
51	      <div className="flex-1 min-w-0">
52	        {/* Top row: dots and connectors */}
53	        <div className="flex items-center">
54	          {effectiveStages.map((stage, i) => {
55	            const isCompleted = !isRejected && i < currentIndex;
56	            const isCurrent = !isRejected && i === currentIndex;
57	            const isUpcoming = isRejected || i > currentIndex;
58	            const stageLabel = effectiveLabels[stage] ?? (stage.charAt(0).toUpperCase() + stage.slice(1));
59	
60	            return (
61	              <Fragment key={stage}>
62	                <TooltipProvider delayDuration={150}>
63	                  <Tooltip>
64	                    <TooltipTrigger asChild>
65	                      <button
66	                        disabled={disabled}
67	                        onClick={(e) => { e.stopPropagation(); onStageChange(stage as HiringStage); }}
68	                        className={cn(
69	                          "relative w-6 h-6 rounded-full flex items-center justify-center text-[11px] font-bold transition-all duration-150 shrink-0",
70	                          "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-1",
71	                          isCompleted && "bg-emerald-500 text-white dark:bg-emerald-600 shadow-sm",
72	                          isCurrent && "bg-primary text-primary-foreground ring-2 ring-primary/30 shadow-sm",
73	                          isUpcoming && "bg-muted border border-border text-muted-foreground",
74	                          !disabled && "cursor-pointer hover:scale-110 hover:shadow",
75	                          disabled && "cursor-default"
76	                        )}
77	                      >
78	                        {isCompleted ? "✓" : i + 1}
79	                      </button>
80	                    </TooltipTrigger>
81	                    <TooltipContent className="text-xs">
82	                      {isCompleted
83	                        ? `${stageLabel} — done`
84	                        : isCurrent
85	                        ? `${stageLabel} — current stage`
86	                        : `Move to ${stageLabel}`}
87	                    </TooltipContent>
88	                  </Tooltip>
89	                </TooltipProvider>
90	
91	                {i < effectiveStages.length - 1 && (
92	                  <div className={cn(
93	                    "h-px flex-1 min-w-[16px] max-w-[48px] transition-colors duration-200 shrink-0",
94	                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
95	                  )} />
96	                )}
97	              </Fragment>
98	            );
99	          })}
100	        </div>
101	
102	        {/* Bottom row: labels aligned under each dot */}
103	        <div className="flex items-start mt-1.5">
104	          {effectiveStages.map((stage, i) => {
105	            const isCompleted = !isRejected && i < currentIndex;
106	            const isCurrent = !isRejected && i === currentIndex;
107	            const stageLabel = effectiveLabels[stage] ?? (stage.charAt(0).toUpperCase() + stage.slice(1));
108	
109	            return (
110	              <Fragment key={stage}>
111	                <span className={cn(
112	                  "w-6 text-center text-[11px] leading-none",
113	                  isCompleted && "text-emerald-600 dark:text-emerald-400",
114	                  isCurrent && "text-primary font-semibold",
115	                  !isCompleted && !isCurrent && "text-muted-foreground"
116	                )}>
117	                  {stageLabel}
118	                </span>
119	                {i < effectiveStages.length - 1 && (
120	                  <div className="flex-1 min-w-[16px] max-w-[48px]" />
121	                )}
122	              </Fragment>
123	            );
124	          })}
125	        </div>
126	      </div>
127	
128	      {/* Reject button — visible on all screen sizes */}
129	      <TooltipProvider delayDuration={150}>
130	        <Tooltip>
131	          <TooltipTrigger asChild>
132	            <Button
133	              variant="ghost"
134	              size="icon"
135	              disabled={disabled}
136	              className={cn(
137	                "h-7 w-7 shrink-0",
138	                isRejected
139	                  ? "text-destructive bg-destructive/10 hover:bg-destructive/20"
140	                  : "text-muted-foreground/40 hover:text-destructive hover:bg-destructive/10"
141	              )}
142	              onClick={(e) => { e.stopPropagation(); onStageChange("rejected"); }}
143	            >
144	              <XCircle className="h-3.5 w-3.5" />
145	            </Button>
146	          </TooltipTrigger>
147	          <TooltipContent className="text-xs">
148	            {isRejected ? "Click any stage to restore" : "Reject candidate"}
149	          </TooltipContent>
150	        </Tooltip>
151	      </TooltipProvider>
152	
153	      {/* Rejected badge */}
154	      {isRejected && (
155	        <Badge variant="destructive" className="text-[11px] shrink-0">Rejected</Badge>
156	      )}
157	
158	      {/* Updated timestamp */}
159	      {updatedAt && (() => {
160	        try {
161	          return (
162	            <span className="text-[11px] text-muted-foreground shrink-0">
163	              Updated {format(new Date(updatedAt), "MMM d")}
164	            </span>
165	          );
166	        } catch {
167	          return null;
168	        }
169	      })()}
170	    </div>
171	  );
172	};
173	
174	export default StageTracker;
175	
