23	// ─── Recommendation options ───────────────────────────────────────────────────
24	
25	const RECOMMENDATIONS: { value: Recommendation; label: string; color: string }[] = [
26	  { value: "strong_yes", label: "Strong Yes",  color: "text-emerald-600 dark:text-emerald-400" },
27	  { value: "yes",        label: "Yes",         color: "text-green-600 dark:text-green-400" },
