33	// ─── StarRating ───────────────────────────────────────────────────────────────
34	
35	function StarRating({
36	  value,
37	  max,
38	  onChange,
39	  disabled,
40	}: {
41	  value: number;
42	  max: number;
43	  onChange: (v: number) => void;
44	  disabled?: boolean;
45	}) {
46	  const [hovered, setHovered] = useState<number | null>(null);
47	  const display = hovered !== null ? hovered : value;
48	
49	  return (
50	    <div className="flex items-center gap-0.5">
51	      {Array.from({ length: max }, (_, i) => i + 1).map((star) => (
52	        <button
53	          key={star}
54	          type="button"
55	          disabled={disabled}
56	          onClick={() => onChange(star)}
57	          onMouseEnter={() => !disabled && setHovered(star)}
58	          onMouseLeave={() => setHovered(null)}
59	          className={cn(
60	            "transition-colors",
61	            disabled ? "cursor-default" : "cursor-pointer hover:scale-110"
62	          )}
63	          aria-label={`Rate ${star} out of ${max}`}
64	        >
65	          <Star
66	            className={cn(
67	              "h-4 w-4 transition-colors",
68	              star <= display
69	                ? "text-amber-400 fill-amber-400"
70	                : "text-muted-foreground/30"
71	            )}
72	          />
73	        </button>
74	      ))}
75	      <span className="text-xs text-muted-foreground ml-1 tabular-nums">
76	        {value}/{max}
77	      </span>
78	    </div>
79	  );
80	}
