82	// ─── ScorecardPanel ───────────────────────────────────────────────────────────
83	
84	interface ScorecardPanelProps {
85	  resumeId: string;
86	  jobId: string;
87	  teamId: string | null | undefined;
88	}
89	
90	export default function ScorecardPanel({ resumeId, jobId, teamId }: ScorecardPanelProps) {
91	  const { user } = useAuth();
92	  const { data: templates, isLoading: templatesLoading } = useScorecardTemplates(teamId);
93	  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
94	
95	  // Determine active template
96	  const activeTemplates = templates ?? [];
97	  const selectedTemplate = activeTemplates.find((t) => t.id === selectedTemplateId) ?? activeTemplates[0] ?? null;
98	
99	  // Set default template when list loads
100	  useEffect(() => {
101	    if (!selectedTemplateId && activeTemplates.length > 0) {
102	      setSelectedTemplateId(activeTemplates[0].id);
103	    }
104	  }, [activeTemplates, selectedTemplateId]);
105	
106	  const { data: responses, isLoading: responsesLoading } = useScorecardResponses(resumeId, jobId);
107	  const submitMutation = useSubmitScorecardResponse();
108	
109	  // Find existing response for the current evaluator + template
110	  const myResponse = responses?.find(
111	    (r) => r.evaluator_id === user?.id && r.template_id === selectedTemplate?.id
112	  );
113	
114	  // Local form state
115	  const [scores, setScores] = useState<Record<string, number>>({});
116	  const [comment, setComment] = useState("");
117	  const [recommendation, setRecommendation] = useState<Recommendation>("neutral");
118	
119	  // Populate form with existing response when it loads
120	  useEffect(() => {
121	    if (myResponse) {
122	      setScores(myResponse.scores ?? {});
123	      setComment(myResponse.overall_comment ?? "");
124	      setRecommendation(myResponse.recommendation ?? "neutral");
125	    } else if (selectedTemplate) {
126	      // Reset scores to 0 for new template
127	      const initial: Record<string, number> = {};
128	      selectedTemplate.criteria.forEach((c) => {
129	        initial[c.id] = 0;
130	      });
131	      setScores(initial);
132	      setComment("");
133	      setRecommendation("neutral");
134	    }
135	  }, [myResponse, selectedTemplate?.id]);
136	
137	  async function handleSubmit() {
138	    if (!selectedTemplate) return;
139	    await submitMutation.mutateAsync({
140	      templateId: selectedTemplate.id,
141	      resumeId,
142	      jobId,
143	      scores,
144	      overallComment: comment.trim() || undefined,
145	      recommendation,
146	    });
147	  }
148	
149	  const isLoading = templatesLoading || responsesLoading;
150	
151	  if (!teamId) return null;
152	
153	  if (isLoading) {
154	    return (
155	      <div className="space-y-3">
156	        <Skeleton className="h-8 w-48" />
157	        <Skeleton className="h-24 w-full" />
158	      </div>
159	    );
160	  }
161	
162	  if (activeTemplates.length === 0) {
163	    return (
164	      <div className="rounded-lg border border-dashed border-border p-4 text-center">
165	        <p className="text-xs text-muted-foreground">
166	          No scorecard templates configured. Ask your team admin to create one.
167	        </p>
168	      </div>
169	    );
170	  }
171	
172	  const isAlreadySubmitted = !!myResponse;
173	
174	  return (
175	    <div className="space-y-4">
176	      {/* Template selector */}
177	      {activeTemplates.length > 1 && (
178	        <Select
179	          value={selectedTemplate?.id ?? ""}
180	          onValueChange={(v) => setSelectedTemplateId(v)}
181	        >
182	          <SelectTrigger className="h-8 text-xs w-full max-w-xs">
183	            <SelectValue placeholder="Select template…" />
184	          </SelectTrigger>
185	          <SelectContent>
186	            {activeTemplates.map((t) => (
187	              <SelectItem key={t.id} value={t.id} className="text-xs">
188	                {t.name}
189	              </SelectItem>
190	            ))}
191	          </SelectContent>
192	        </Select>
193	      )}
194	
195	      {selectedTemplate && (
196	        <>
197	          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
198	            {selectedTemplate.name}
199	            {isAlreadySubmitted && (
200	              <span className="ml-2 text-emerald-600 dark:text-emerald-400 normal-case">
201	                (submitted — you can update)
202	              </span>
203	            )}
204	          </p>
205	
206	          {/* Criteria */}
207	          <div className="space-y-3">
208	            {selectedTemplate.criteria.map((criterion) => (
209	              <div key={criterion.id} className="space-y-1">
210	                <div>
211	                  <Label className="text-xs font-medium">{criterion.label}</Label>
212	                  {criterion.description && (
213	                    <p className="text-[11px] text-muted-foreground leading-snug">{criterion.description}</p>
214	                  )}
215	                </div>
216	                <StarRating
217	                  value={scores[criterion.id] ?? 0}
218	                  max={criterion.max_score}
219	                  onChange={(v) => setScores((prev) => ({ ...prev, [criterion.id]: v }))}
220	                />
221	              </div>
222	            ))}
223	          </div>
224	
225	          {/* Overall comment */}
226	          <div className="space-y-1">
227	            <Label className="text-xs font-medium">Overall Comments</Label>
228	            <Textarea
229	              placeholder="Any additional observations about this candidate…"
230	              value={comment}
231	              onChange={(e) => setComment(e.target.value)}
232	              className="text-xs min-h-[72px] resize-none"
233	              maxLength={1000}
234	            />
235	          </div>
236	
237	          {/* Recommendation */}
238	          <div className="space-y-1.5">
239	            <Label className="text-xs font-medium">Recommendation</Label>
240	            <div className="flex flex-wrap gap-2">
241	              {RECOMMENDATIONS.map((rec) => (
