250	                      : "border-border text-muted-foreground hover:border-muted-foreground"
251	                  )}
252	                >
253	                  {rec.label}
254	                </button>
255	              ))}
256	            </div>
257	          </div>
258	
259	          {/* Submit */}
260	          <Button
261	            size="sm"
262	            className="w-full h-8 text-xs"
263	            onClick={handleSubmit}
264	            disabled={submitMutation.isPending}
265	          >
