1	import { useScorecardResponses, type Recommendation } from "@/hooks/useScorecardResponses";
2	import { useScorecardTemplates } from "@/hooks/useScorecardTemplates";
3	import { Skeleton } from "@/components/ui/skeleton";
4	import { cn } from "@/lib/utils";
5	
6	// ─── Types ────────────────────────────────────────────────────────────────────
7	
8	interface ScorecardSummaryProps {
9	  resumeId: string;
10	  jobId: string;
11	  teamId: string | null | undefined;
12	  compact?: boolean;
13	}
14	
15	// ─── Recommendation label + color map ─────────────────────────────────────────
16	
17	const REC_LABEL: Record<Recommendation, string> = {
18	  strong_yes: "Strong Yes",
19	  yes: "Yes",
20	  neutral: "Neutral",
21	  no: "No",
22	  strong_no: "Strong No",
23	};
24	
25	const REC_COLOR: Record<Recommendation, string> = {
26	  strong_yes: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400",
27	  yes:        "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400",
28	  neutral:    "bg-muted text-muted-foreground",
29	  no:         "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400",
30	  strong_no:  "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
31	};
32	
33	// ─── ScorecardSummary ─────────────────────────────────────────────────────────
34	
35	export default function ScorecardSummary({ resumeId, jobId, teamId, compact = false }: ScorecardSummaryProps) {
36	  const { data: responses, isLoading: responsesLoading } = useScorecardResponses(resumeId, jobId);
37	  const { data: templates, isLoading: templatesLoading } = useScorecardTemplates(teamId);
38	
39	  const isLoading = responsesLoading || templatesLoading;
40	
41	  if (!teamId) return null;
42	  if (isLoading) {
43	    return compact ? null : (
44	      <div className="space-y-2">
45	        <Skeleton className="h-4 w-32" />
46	        <Skeleton className="h-16 w-full" />
47	      </div>
48	    );
49	  }
50	
51	  const allResponses = responses ?? [];
52	  if (allResponses.length === 0) {
53	    if (compact) return null;
54	    return (
55	      <p className="text-xs text-muted-foreground italic">No evaluations submitted yet.</p>
56	    );
57	  }
58	
59	  // Count recommendations
60	  const recCounts: Partial<Record<Recommendation, number>> = {};
61	  allResponses.forEach((r) => {
62	    recCounts[r.recommendation] = (recCounts[r.recommendation] ?? 0) + 1;
63	  });
64	
65	  // Per-criterion average scores across all responses
66	  // Merge all criteria from all templates referenced
67	  const criteriaMap: Map<string, { label: string; max_score: number; scores: number[] }> = new Map();
68	
69	  allResponses.forEach((response) => {
70	    const template = (templates ?? []).find((t) => t.id === response.template_id);
71	    if (!template) return;
72	    template.criteria.forEach((c) => {
73	      const score = response.scores[c.id];
74	      if (score === undefined || score === 0) return;
75	      if (!criteriaMap.has(c.id)) {
76	        criteriaMap.set(c.id, { label: c.label, max_score: c.max_score, scores: [] });
77	      }
78	      criteriaMap.get(c.id)!.scores.push(score);
79	    });
80	  });
81	
82	  const criteriaAverages = Array.from(criteriaMap.entries()).map(([id, info]) => ({
83	    id,
84	    label: info.label,
85	    max_score: info.max_score,
86	    avg: info.scores.reduce((a, b) => a + b, 0) / info.scores.length,
87	  }));
88	
89	  if (compact) {
90	    return (
91	      <div className="flex items-center gap-2 flex-wrap">
92	        <span className="text-[11px] text-muted-foreground font-medium">
93	          {allResponses.length} eval{allResponses.length !== 1 ? "s" : ""}
94	        </span>
95	        {(Object.entries(recCounts) as [Recommendation, number][]).map(([rec, count]) => (
96	          <span
97	            key={rec}
98	            className={cn("text-[10px] px-1.5 py-0.5 rounded-full font-medium", REC_COLOR[rec])}
99	          >
100	            {count} {REC_LABEL[rec]}
101	          </span>
102	        ))}
103	      </div>
104	    );
105	  }
106	
107	  return (
108	    <div className="space-y-4">
109	      {/* Header */}
110	      <div className="flex items-center justify-between">
111	        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
112	          Evaluations ({allResponses.length})
113	        </p>
114	      </div>
115	
116	      {/* Recommendation distribution */}
117	      <div className="flex flex-wrap gap-2">
118	        {(Object.entries(recCounts) as [Recommendation, number][]).map(([rec, count]) => (
119	          <span
120	            key={rec}
121	            className={cn("text-xs px-2 py-0.5 rounded-full font-medium", REC_COLOR[rec])}
122	          >
123	            {count} {REC_LABEL[rec]}
124	          </span>
125	        ))}
126	      </div>
127	
128	      {/* Per-criterion averages */}
129	      {criteriaAverages.length > 0 && (
130	        <div className="space-y-2">
131	          {criteriaAverages.map((ca) => {
132	            const pct = Math.round((ca.avg / ca.max_score) * 100);
133	            return (
134	              <div key={ca.id} className="space-y-1">
135	                <div className="flex items-center justify-between">
136	                  <span className="text-xs text-muted-foreground">{ca.label}</span>
137	                  <span className="text-xs font-semibold tabular-nums">
138	                    {ca.avg.toFixed(1)}/{ca.max_score}
139	                  </span>
140	                </div>
141	                <div className="h-1.5 w-full rounded-full bg-muted overflow-hidden">
142	                  <div
143	                    className={cn(
144	                      "h-full rounded-full transition-all",
145	                      pct >= 70
146	                        ? "bg-emerald-500"
147	                        : pct >= 40
148	                        ? "bg-amber-500"
149	                        : "bg-red-500"
150	                    )}
151	                    style={{ width: `${pct}%` }}
152	                  />
153	                </div>
154	              </div>
155	            );
156	          })}
157	        </div>
158	      )}
159	    </div>
160	  );
161	}
