64	
65	  const { data: interviews, isLoading } = useQuery({
66	    queryKey: ["interviews", resumeId],
67	    queryFn: async () => {
68	      const { data, error } = await (supabase as any)
69	        .from("interviews")
70	        .select("id, scheduled_at, duration_minutes, status, meeting_link, notes, interviewer_id, candidate_name")
71	        .eq("resume_id", resumeId)
72	        .eq("job_id", jobId)
73	        .order("scheduled_at", { ascending: false });
74	      if (error) throw error;
75	      return (data ?? []) as Interview[];
76	    },
77	    staleTime: 30_000,
78	  });
