13	
14	interface AssigneeSelectorProps {
15	  resumeId: string;
16	  assignedTo: string | null | undefined;
17	  members: TeamMember[];
18	  disabled?: boolean;
19	  onAssigned?: (userId: string | null) => void;
20	}
21	
22	export default function AssigneeSelector({
23	  resumeId,
24	  assignedTo,
25	  members,
26	  disabled = false,
27	  onAssigned,
28	}: AssigneeSelectorProps) {
29	  const [saving, setSaving] = useState(false);
30	
31	  const handleChange = async (value: string) => {
32	    const userId = value === "__none__" ? null : value;
33	    setSaving(true);
34	    try {
35	      const { error } = await (supabase as any)
36	        .from("resumes")
37	        .update({ assigned_to: userId })
38	        .eq("id", resumeId);
39	      if (error) throw error;
40	      onAssigned?.(userId);
41	      toast.success(userId ? "Assignee updated" : "Assignee removed");
42	    } catch {
43	      toast.error("Failed to update assignee");
44	    } finally {
45	      setSaving(false);
46	    }
47	  };
48	
49	  const displayValue = assignedTo ?? "__none__";
50	
51	  const getMemberLabel = (member: TeamMember) => {
52	    return member.email ?? `User ${member.user_id.slice(0, 8)}`;
53	  };
54	
55	  return (
56	    <div className="space-y-2">
57	      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
58	        <UserCheck className="h-3 w-3" /> Assigned To
59	      </p>
60	      <Select
61	        value={displayValue}
62	        onValueChange={handleChange}
63	        disabled={disabled || saving || members.length === 0}
64	      >
65	        <SelectTrigger className="h-8 text-xs">
66	          {saving ? (
67	            <span className="flex items-center gap-1.5 text-muted-foreground">
68	              <Loader2 className="h-3 w-3 animate-spin" />
69	              Saving…
70	            </span>
71	          ) : (
72	            <SelectValue placeholder={members.length === 0 ? "No team members" : "Unassigned"} />
73	          )}
74	        </SelectTrigger>
75	        <SelectContent>
76	          <SelectItem value="__none__" className="text-xs text-muted-foreground">
77	            Unassigned
78	          </SelectItem>
79	          {members.map((m) => (
80	            <SelectItem key={m.user_id} value={m.user_id} className="text-xs">
81	              {getMemberLabel(m)}
82	              {m.role === "owner" && (
83	                <span className="ml-1 text-[10px] text-muted-foreground">(owner)</span>
84	              )}
85	            </SelectItem>
86	          ))}
87	        </SelectContent>
88	      </Select>
89	    </div>
90	  );
91	}
