29	  onPoolChange,
30	  size = "sm",
31	  variant = "outline",
32	}: AddToPoolButtonProps) => {
33	  const { user } = useAuth();
34	  const [inPool, setInPool] = useState(isInPool);
35	  const [loading, setLoading] = useState(false);
36	
37	  const handleToggle = async () => {
