16	
17	interface CandidateTagInputProps {
18	  resumeId: string;
19	  tags: CandidateTag[];
20	  onAdd: (params: { resumeId: string; tag: string; color?: string }) => void;
21	  onRemove: (tagId: string) => void;
22	  disabled?: boolean;
23	}
24	
25	export default function CandidateTagInput({
26	  resumeId,
27	  tags,
28	  onAdd,
29	  onRemove,
30	  disabled = false,
31	}: CandidateTagInputProps) {
32	  const [inputValue, setInputValue] = useState("");
33	  const [showSuggestions, setShowSuggestions] = useState(false);
34	  const inputRef = useRef<HTMLInputElement>(null);
35	
36	  const existingTagNames = new Set(tags.map((t) => t.tag.toLowerCase()));
37	
38	  const filteredSuggestions = PRESET_TAGS.filter(
39	    (p) =>
40	      !existingTagNames.has(p.tag.toLowerCase()) &&
41	      (inputValue === "" || p.tag.toLowerCase().includes(inputValue.toLowerCase()))
42	  );
43	
44	  const handleAddTag = useCallback(
45	    (tag: string, color?: string) => {
46	      const trimmed = tag.trim();
47	      if (!trimmed || existingTagNames.has(trimmed.toLowerCase())) return;
48	      onAdd({ resumeId, tag: trimmed, color });
49	      setInputValue("");
50	      setShowSuggestions(false);
51	    },
52	    [resumeId, onAdd, existingTagNames]
53	  );
54	
55	  const handleKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
56	    if (e.key === "Enter" && inputValue.trim()) {
57	      e.preventDefault();
58	      handleAddTag(inputValue.trim());
59	    }
60	    if (e.key === "Escape") {
61	      setShowSuggestions(false);
62	      inputRef.current?.blur();
63	    }
64	    if (e.key === "Backspace" && inputValue === "" && tags.length > 0) {
65	      const last = tags[tags.length - 1];
66	      onRemove(last.id);
67	    }
68	  };
69	
70	  return (
71	    <div className="space-y-2">
72	      <p className="text-[11px] font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
