81	            className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium text-white"
82	            style={{ backgroundColor: t.color }}
83	          >
84	            {t.tag}
85	            {!disabled && (
86	              <button
87	                onClick={() => onRemove(t.id)}
88	                className="hover:opacity-70 transition-opacity ml-0.5"
89	                aria-label={`Remove tag ${t.tag}`}
90	              >
91	                <X className="h-2.5 w-2.5" />
92	              </button>
93	            )}
94	          </span>
95	        ))}
96	      </div>
97	
98	      {/* Input + autocomplete */}
99	      {!disabled && (
100	        <div className="relative">
101	          <div className="flex items-center gap-1.5">
102	            <div className="relative flex-1">
103	              <Input
104	                ref={inputRef}
105	                value={inputValue}
106	                onChange={(e) => {
107	                  setInputValue(e.target.value);
108	                  setShowSuggestions(true);
109	                }}
110	                onFocus={() => setShowSuggestions(true)}
111	                onBlur={() => setTimeout(() => setShowSuggestions(false), 150)}
112	                onKeyDown={handleKeyDown}
113	                placeholder="Add tag…"
114	                className="h-7 text-xs pr-2"
115	                disabled={disabled}
116	              />
117	            </div>
118	            {inputValue.trim() && (
119	              <button
120	                className="flex items-center gap-0.5 text-xs text-primary hover:text-primary/80 transition-colors shrink-0"
121	                onMouseDown={(e) => {
122	                  e.preventDefault();
123	                  handleAddTag(inputValue.trim());
124	                }}
125	              >
126	                <Plus className="h-3 w-3" /> Add
127	              </button>
128	            )}
129	          </div>
130	
131	          {/* Suggestions dropdown */}
132	          {showSuggestions && filteredSuggestions.length > 0 && (
133	            <div className="absolute z-50 top-full mt-1 w-full bg-popover border border-border rounded-md shadow-md overflow-hidden">
134	              {filteredSuggestions.slice(0, 6).map((p) => (
135	                <button
136	                  key={p.tag}
137	                  className="w-full flex items-center gap-2 px-3 py-1.5 text-xs hover:bg-muted/60 transition-colors text-left"
138	                  onMouseDown={(e) => {
139	                    e.preventDefault();
140	                    handleAddTag(p.tag, p.color);
141	                  }}
142	                >
143	                  <span
144	                    className="h-2 w-2 rounded-full shrink-0"
145	                    style={{ backgroundColor: p.color }}
146	                  />
147	                  {p.tag}
148	                </button>
149	              ))}
150	            </div>
151	          )}
152	        </div>
